   RESET & BASE
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-base:        #0d0d0f;
  --bg-surface:     #16161a;
  --bg-elevated:    #1e1e24;
  --bg-card:        #222228;
  --border:         #2e2e38;
  --accent:         #e8c46a;
  --accent-dim:     #b8943a;
  --accent-subtle:  rgba(232,196,106,.12);
  --red:            #e85454;
  --green:          #4ade80;
  --text-primary:   #f0f0f5;
  --text-secondary: #9090a8;
  --text-muted:     #5a5a72;
  --radius-sm:      6px;
  --radius-md:      12px;
  --radius-lg:      20px;
  --shadow-card:    0 4px 24px rgba(0,0,0,.5);
  --transition:     0.22s ease;
  --font-sans:      'Inter', system-ui, -apple-system, sans-serif;
  --font-display:   'Playfair Display', Georgia, serif;
}

html { scroll-behavior: smooth; }

body {
  background-color: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

/* ============================================================
   SKIP LINK
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ============================================================
   HEADER / NAV
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.88);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: .02em;
  white-space: nowrap;
}

.nav-links {
  display: flex;
  list-style: none;
  gap: .25rem;
  margin-right: auto;
}

.nav-links a {
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a:focus-visible {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
}

.nav-icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.nav-icon-btn:hover,
.nav-icon-btn:focus-visible {
  color: var(--text-primary);
  background: var(--bg-elevated);
}
.nav-icon-btn svg { width: 20px; height: 20px; }

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  background: var(--accent);
  color: #000;
  font-size: 10px;
  font-weight: 700;
  line-height: 16px;
  text-align: center;
  border-radius: 8px;
}

.nav-hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  padding: 8px;
}
.nav-hamburger span {
  display: block;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  min-height: 580px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg-surface);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,196,106,.08) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(232,196,106,.04) 0%, transparent 60%);
}

.hero-grid-overlay {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: .25;
}

.hero-inner {
  position: relative;
  max-width: 1320px;
  margin: 0 auto;
  padding: 5rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  width: 100%;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .35rem .85rem;
  background: var(--accent-subtle);
  border: 1px solid rgba(232,196,106,.25);
  border-radius: 999px;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1.25rem;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -.01em;
  margin-bottom: 1.25rem;
}

.hero-title em {
  font-style: normal;
  color: var(--accent);
}

.hero-desc {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  max-width: 480px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .7rem 1.4rem;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 600;
  line-height: 1;
  transition: all var(--transition);
}
.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.btn-primary {
  background: var(--accent);
  color: #000;
}
.btn-primary:hover {
  background: #f0d080;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(232,196,106,.3);
}

.btn-ghost {
  border: 1px solid var(--border);
  color: var(--text-secondary);
  background: transparent;
}
.btn-ghost:hover {
  border-color: var(--text-muted);
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.hero-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition);
}
.hero-card:hover { transform: translateY(-3px); }

.hero-card-img {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.hero-card:first-child { margin-top: 2rem; }

.hero-card-body {
  padding: .75rem 1rem;
}
.hero-card-label {
  font-size: .75rem;
  color: var(--text-muted);
  margin-bottom: .2rem;
}
.hero-card-name {
  font-weight: 600;
  font-size: .9rem;
}
.hero-card-price {
  font-size: .85rem;
  color: var(--accent);
  font-weight: 600;
  margin-top: .2rem;
}

/* ============================================================
   SECTION SHARED
   ============================================================ */
.section {
  padding: 5rem 1.5rem;
}

.section-inner {
  max-width: 1320px;
  margin: 0 auto;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}

.section-label {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .35rem;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  line-height: 1.2;
}

.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  transition: gap var(--transition);
}
.section-link:hover { gap: .7rem; }
.section-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ============================================================
   CATEGORY STRIP
   ============================================================ */
.category-strip {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 1.5rem;
  overflow-x: auto;
  scrollbar-width: none;
}
.category-strip::-webkit-scrollbar { display: none; }

.category-strip-inner {
  max-width: 1320px;
  margin: 0 auto;
  display: flex;
  gap: .75rem;
  justify-content: center;
  flex-wrap: wrap;
}

.category-chip {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .55rem 1.1rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elevated);
  font-size: .8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all var(--transition);
}
.category-chip:hover,
.category-chip.active {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-subtle);
}
.category-chip:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.category-chip-icon { font-size: 1rem; }

/* ============================================================
   FEATURED PRODUCTS
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card);
  border-color: rgba(232,196,106,.2);
}

.product-card-media {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  overflow: hidden;
}

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .25rem .6rem;
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-new { background: var(--accent); color: #000; }
.badge-sale { background: var(--red); color: #fff; }
.badge-hot { background: #ff6b35; color: #fff; }

.product-wishlist {
  position: absolute;
  top: .6rem;
  right: .6rem;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(13,13,15,.7);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: color var(--transition), background var(--transition);
}
.product-wishlist:hover,
.product-wishlist.active {
  color: var(--red);
  background: rgba(232,84,84,.15);
}
.product-wishlist svg { width: 16px; height: 16px; }

.product-card-body {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-category {
  font-size: .7rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: .3rem;
}

.product-name {
  font-weight: 600;
  font-size: .9375rem;
  line-height: 1.35;
  margin-bottom: .4rem;
  color: var(--text-primary);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  margin-bottom: .6rem;
}

.stars {
  display: flex;
  gap: 2px;
  color: var(--accent);
  font-size: .75rem;
}
.star-empty { color: var(--text-muted); }

.rating-count {
  font-size: .75rem;
  color: var(--text-muted);
}

.product-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: auto;
  margin-bottom: .85rem;
}

.price-current {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--text-primary);
}

.price-original {
  font-size: .85rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-save {
  font-size: .75rem;
  font-weight: 700;
  color: var(--green);
  margin-left: auto;
}

.btn-add-cart {
  width: 100%;
  padding: .65rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  transition: all var(--transition);
}
.btn-add-cart svg { width: 16px; height: 16px; }
.btn-add-cart:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: #000;
}
.btn-add-cart:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.btn-add-cart.added {
  background: var(--green);
  border-color: var(--green);
  color: #000;
}

/* ============================================================
   DEALS SECTION
   ============================================================ */
.deals-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 1.25rem;
}

.deal-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-card);
}

.deal-card--featured {
  grid-row: span 2;
}

.deal-card-media {
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  flex-shrink: 0;
}
.deal-card--featured .deal-card-media { aspect-ratio: 4/5; }
.deal-card:not(.deal-card--featured) .deal-card-media { aspect-ratio: 16/9; }

.deal-card-body {
  padding: 1.1rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  padding: .25rem .65rem;
  background: rgba(232,84,84,.15);
  border: 1px solid rgba(232,84,84,.3);
  color: var(--red);
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: .6rem;
  width: fit-content;
}
.deal-tag svg { width: 12px; height: 12px; }

.deal-name {
  font-weight: 700;
  font-size: 1rem;
  line-height: 1.3;
  margin-bottom: .4rem;
}
.deal-card--featured .deal-name { font-size: 1.2rem; }

.deal-desc {
  font-size: .8125rem;
  color: var(--text-secondary);
  margin-bottom: .75rem;
  line-height: 1.55;
}

.deal-price-block {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-bottom: .5rem;
}
.deal-price-now {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
}
.deal-price-was {
  font-size: .85rem;
  color: var(--text-muted);
  text-decoration: line-through;
}
.deal-discount {
  font-size: .8rem;
  font-weight: 700;
  color: var(--green);
}

.deal-countdown {
  display: flex;
  gap: .4rem;
  margin-bottom: .9rem;
  align-items: center;
}
.deal-countdown-label {
  font-size: .7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-right: .1rem;
}
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.countdown-num {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .25rem .5rem;
  font-size: .9rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  min-width: 32px;
  text-align: center;
  color: var(--accent);
}
.countdown-sep {
  font-weight: 700;
  color: var(--text-muted);
  font-size: .9rem;
  align-self: flex-start;
  margin-top: .2rem;
}

.deal-stock-bar {
  margin-bottom: .85rem;
}
.deal-stock-label {
  display: flex;
  justify-content: space-between;
  font-size: .72rem;
  color: var(--text-muted);
  margin-bottom: .35rem;
}
.stock-bar-track {
  height: 5px;
  background: var(--bg-elevated);
  border-radius: 9px;
  overflow: hidden;
}
.stock-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--red), #ff6b35);
  border-radius: 9px;
  transition: width 1s ease;
}

.btn-deal {
  margin-top: auto;
  padding: .65rem;
  background: var(--red);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .875rem;
  text-align: center;
  transition: background var(--transition), transform var(--transition);
  display: block;
}
.btn-deal:hover {
  background: #ff6060;
  transform: translateY(-1px);
}
.btn-deal:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 3px;
}

/* ============================================================
   EDITORIAL
   ============================================================ */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}

.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.editorial-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-card);
}
.editorial-card:focus-within {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-md);
}

.editorial-card--hero {
  grid-column: 1 / 3;
  grid-row: 1 / 3;
  flex-direction: column;
}

.editorial-card-media {
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}
.editorial-card--hero .editorial-card-media { aspect-ratio: 16/10; font-size: 6rem; }
.editorial-card:not(.editorial-card--hero) .editorial-card-media { aspect-ratio: 16/9; }

.editorial-card-media-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(13,13,15,.7) 0%, transparent 60%);
}

.editorial-card-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.editorial-tag {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  padding: .2rem .6rem;
  border-radius: 999px;
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  margin-bottom: .6rem;
  width: fit-content;
}
.tag-style { background: rgba(232,196,106,.15); color: var(--accent); }
.tag-tech  { background: rgba(74,222,128,.1);  color: var(--green); }
.tag-life  { background: rgba(139,92,246,.15);  color: #a78bfa; }
.tag-trend { background: rgba(232,84,84,.12);   color: #f87171; }

.editorial-title {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: .5rem;
  color: var(--text-primary);
}
.editorial-card--hero .editorial-title { font-size: 1.35rem; }

.editorial-excerpt {
  font-size: .8125rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: .85rem;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}

.editorial-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  font-size: .75rem;
  color: var(--text-muted);
}

.editorial-author {
  display: flex;
  align-items: center;
  gap: .5rem;
}
.author-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .65rem;
  font-weight: 700;
  color: var(--accent);
  flex-shrink: 0;
}

.read-more {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  font-size: .8rem;
  font-weight: 600;
  color: var(--accent);
  transition: gap var(--transition);
}
.read-more:hover { gap: .5rem; }

/* ============================================================
   NEWSLETTER
   ============================================================ */
.newsletter-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
}

.newsletter-inner {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.newsletter-icon {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.newsletter-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  margin-bottom: .75rem;
}

.newsletter-desc {
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
  font-size: .9375rem;
}

.newsletter-form {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-input {
  flex: 1;
  min-width: 220px;
  padding: .75rem 1.1rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
