.cart-items::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }

.cart-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .75rem;
  color: var(--text-muted);
  text-align: center;
  padding: 3rem 1rem;
}
.cart-empty-icon { font-size: 3rem; }
.cart-empty p { font-size: .9rem; }

.cart-item {
  display: flex;
  gap: .85rem;
  padding: .85rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}
.cart-item-emoji {
  font-size: 2rem;
  width: 52px;
  height: 52px;
  background: var(--bg-elevated);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.cart-item-info { flex: 1; min-width: 0; }
.cart-item-name {
