  font-weight: 600;
  margin-top: .1rem;
}
.cart-item-qty {
  display: flex;
  align-items: center;
  gap: .4rem;
  margin-top: .4rem;
}
.qty-btn {
  width: 22px;
  height: 22px;
  border-radius: 4px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  font-size: .9rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  transition: all var(--transition);
}
.qty-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}
.qty-num { font-size: .8rem; font-weight: 600; min-width: 16px; text-align: center; }
.cart-item-remove {
  color: var(--text-muted);
  font-size: .85rem;
  padding: .25rem;
  transition: color var(--transition);
  align-self: flex-start;
}
.cart-item-remove:hover { color: var(--red); }

.cart-footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--border);
}

.cart-totals {
  margin-bottom: 1rem;
}
.cart-total-row {
  display: flex;
  justify-content: space-between;
  font-size: .875rem;
  color: var(--text-secondary);
  margin-bottom: .4rem;
