  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  padding-top: .5rem;
  border-top: 1px solid var(--border);
  margin-top: .4rem;
}

.btn-checkout {
  display: block;
  width: 100%;
  padding: .85rem;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  font-size: .9375rem;
  border-radius: var(--radius-sm);
  text-align: center;
  transition: background var(--transition), transform var(--transition);
}
.btn-checkout:hover {
  background: #f0d080;
  transform: translateY(-1px);
}
.btn-checkout:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--featured { grid-row: span 1; }
  .deal-card--featured .deal-card-media { aspect-ratio: 16/9; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }

  .hero-inner {
    grid-template-columns: 1fr;
    padding: 3rem 1.5rem;
  }
  .hero-visual { display: none; }

  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--hero { grid-column: auto; grid-row: auto; }

  .footer-grid { grid-template-columns: 1fr; gap: 1.75rem; }
}

@media (max-width: 500px) {
  .products-grid { grid-template-columns: 1fr 1fr; gap: .75rem; }
  .category-strip-inner { flex-wrap: nowrap; justify-content: flex-start; }
  .cart-drawer { width: 100vw; }
}

/* ============================================================
   FOCUS VISIBLE UTILITIES
   ============================================================ */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
:focus:not(:focus-visible) { outline: none; }
