+  font-size: 1rem;
+  line-height: 1.3;
+  margin-bottom: .4rem;
+}
+.deal-card--featured .deal-name { font-size: 1.2rem; }
+
+.deal-desc {
+  font-size: .8125rem;
+  color: var(--text-secondary);
+  margin-bottom: .75rem;
+  line-height: 1.55;
+}
+
+.deal-price-block {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  margin-bottom: .5rem;
+}
+.deal-price-now {
+  font-size: 1.25rem;
+  font-weight: 800;
+  color: var(--text-primary);
+}
+.deal-price-was {
+  font-size: .85rem;
+  color: var(--text-muted);
+  text-decoration: line-through;
+}
+.deal-discount {
+  font-size: .8rem;
+  font-weight: 700;
+  color: var(--green);
+}
+
+.deal-countdown {
