   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-base:        #0d0d0f;
  --bg-surface:     #16161a;
  --bg-elevated:    #1e1e24;
  --bg-card:        #222228;
  --border:         #2e2e38;
