}

/* ============================================================
   SECTION SHARED
   ============================================================ */
.section {
  padding: 5rem 1.5rem;
}

.section-inner {
  max-width: 1320px;
  margin: 0 auto;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
