  box-shadow: var(--shadow-card);
  border-color: rgba(232,196,106,.2);
}

.product-card-media {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  overflow: hidden;
}

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .25rem .6rem;
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-new { background: var(--accent); color: #000; }
.badge-sale { background: var(--red); color: #fff; }
.badge-hot { background: #ff6b35; color: #fff; }

.product-wishlist {
