  document.getElementById('cart-shipping').textContent = shipping === 0 ? 'FREE' : formatPrice(shipping);
  cartTotalEl.textContent = formatPrice(total + shipping);

  // bind qty and remove buttons
  cartItemsEl.querySelectorAll('.qty-btn').forEach(btn => {
    btn.addEventListener('click', () => changeQty(+btn.dataset.id, +btn.dataset.delta));
  });
  cartItemsEl.querySelectorAll('.cart-item-remove').forEach(btn => {
    btn.addEventListener('click', () => removeFromCart(+btn.dataset.id));
  });
}

// Initial render
renderCart();

// ============================================================
// PRODUCTS
// ============================================================
function renderProducts(products) {
  return products.map(p => {
    const disc = discount(p.original, p.price);
    return `
      <article class="product-card" aria-label="${p.name}">
        <div class="product-card-media">
          <span aria-hidden="true">${p.emoji}</span>
          ${p.badge ? `<span class="product-badge badge-${p.badge}" aria-label="${p.badge} item">${p.badge}</span>` : ''}
          <button class="product-wishlist" aria-label="Add ${p.name} to wishlist" aria-pressed="false" data-id="${p.id}">
            <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
            </svg>
          </button>
        </div>
        <div class="product-card-body">
          <div class="product-category">${p.category}</div>
          <h3 class="product-name">${p.name}</h3>
          <div class="product-rating">
            <div class="stars" aria-hidden="true">${stars(p.rating)}</div>
            <span class="rating-count">(${p.reviews.toLocaleString()})</span>
            <span class="sr-only">${p.rating} out of 5 stars, ${p.reviews} reviews</span>
          </div>
          <div class="product-price-row">
            <span class="price-current">${formatPrice(p.price)}</span>
            <span class="price-original">${formatPrice(p.original)}</span>
            <span class="price-save">−${disc}%</span>
          </div>
          <button class="btn-add-cart" data-id="${p.id}" aria-label="Add ${p.name} to cart, ${formatPrice(p.price)}">
            <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
              <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/>
            </svg>
            Add to Cart
          </button>
        </div>
      </article>`;
  }).join('');
}

const productsGrid = document.getElementById('products-grid');
productsGrid.innerHTML = renderProducts(PRODUCTS);

// Bind add-to-cart
productsGrid.querySelectorAll('.btn-add-cart').forEach(btn => {
  btn.addEventListener('click', () => {
    const product = PRODUCTS.find(p => p.id === +btn.dataset.id);
    addToCart(product);
    btn.classList.add('added');
    btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Added!`;
    btn.setAttribute('aria-label', `${product.name} added to cart`);
    setTimeout(() => {
      btn.classList.remove('added');
      btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg> Add to Cart`;
      btn.setAttribute('aria-label', `Add ${product.name} to cart, ${formatPrice(product.price)}`);
    }, 2000);
  });
});

// Bind wishlist
productsGrid.querySelectorAll('.product-wishlist').forEach(btn => {
  btn.addEventListener('click', () => {
    const isActive = btn.classList.toggle('active');
    btn.setAttribute('aria-pressed', isActive);
    const name = btn.closest('.product-card').querySelector('.product-name').textContent;
    showToast(isActive ? '❤️' : '🤍', isActive ? `${name} saved to wishlist` : `${name} removed from wishlist`);
  });
});

// ============================================================
// DEALS
// ============================================================
function renderDeal(deal) {
  const disc = discount(deal.original, deal.price);
  const pct  = Math.round((deal.stockTotal - deal.stock) / deal.stockTotal * 100);
  const { h, m, s } = formatCountdown(deal.endsIn);

  return `
    <article class="deal-card${deal.featured ? ' deal-card--featured' : ''}" aria-label="${deal.name} deal, ${disc}% off">
      <div class="deal-card-media" aria-hidden="true">${deal.emoji}</div>
      <div class="deal-card-body">
        <div class="deal-tag" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>
          Flash Deal
        </div>
        <h3 class="deal-name">${deal.name}</h3>
        <p class="deal-desc">${deal.desc}</p>
        <div class="deal-price-block">
          <span class="deal-price-now">${formatPrice(deal.price)}</span>
          <span class="deal-price-was">${formatPrice(deal.original)}</span>
          <span class="deal-discount" aria-label="${disc}% savings">−${disc}%</span>
        </div>
        <div class="deal-countdown" aria-label="Offer ends in ${h} hours ${m} minutes ${s} seconds">
          <span class="deal-countdown-label" aria-hidden="true">Ends in</span>
          <div class="countdown-unit" aria-hidden="true">
            <span class="countdown-num" id="cd-h-${deal.id}">${h}</span>
          </div>
          <span class="countdown-sep" aria-hidden="true">:</span>
          <div class="countdown-unit" aria-hidden="true">
            <span class="countdown-num" id="cd-m-${deal.id}">${m}</span>
          </div>
          <span class="countdown-sep" aria-hidden="true">:</span>
          <div class="countdown-unit" aria-hidden="true">
            <span class="countdown-num" id="cd-s-${deal.id}">${s}</span>
          </div>
        </div>
        <div class="deal-stock-bar">
          <div class="deal-stock-label">
            <span>Sold: <strong>${pct}%</strong></span>
            <span>Only <strong>${deal.stock}</strong> left</span>
          </div>
          <div class="stock-bar-track" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="${pct}% sold">
            <div class="stock-bar-fill" style="width: ${pct}%"></div>
          </div>
        </div>
        <a href="#" class="btn-deal" role="button" aria-label="Grab the deal on ${deal.name} for ${formatPrice(deal.price)}">Grab This Deal →</a>
      </div>
    </article>`;
}

document.getElementById('deals-grid').innerHTML = DEALS.map(renderDeal).join('');

// Countdown tick
function tickCountdowns() {
  DEALS.forEach(deal => {
    if (deal.endsIn <= 0) return;
    deal.endsIn--;
    const { h, m, s } = formatCountdown(deal.endsIn);
    const hEl = document.getElementById(`cd-h-${deal.id}`);
    const mEl = document.getElementById(`cd-m-${deal.id}`);
    const sEl = document.getElementById(`cd-s-${deal.id}`);
    if (hEl) hEl.textContent = h;
    if (mEl) mEl.textContent = m;
    if (sEl) sEl.textContent = s;
  });
}
setInterval(tickCountdowns, 1000);

// ============================================================
// EDITORIAL
// ============================================================
function renderArticle(a) {
  const tagClass = { style: 'tag-style', tech: 'tag-tech', life: 'tag-life', trend: 'tag-trend' }[a.tag];
  return `
    <article class="editorial-card${a.hero ? ' editorial-card--hero' : ''}" aria-label="${a.title}">
      <div class="editorial-card-media" aria-hidden="true">
        ${a.emoji}
