        <h3 class="editorial-title">${a.title}</h3>
        <p class="editorial-excerpt">${a.excerpt}</p>
        <div class="editorial-meta">
          <div class="editorial-author">
            <div class="author-avatar" aria-hidden="true">${a.author}</div>
            <span>${a.authorName} · ${a.date}</span>
