    </article>`;
}

document.getElementById('editorial-grid').innerHTML = ARTICLES.map(renderArticle).join('');

// ============================================================
// CATEGORY FILTER
// ============================================================
document.querySelectorAll('.category-chip').forEach(chip => {
  chip.addEventListener('click', () => {
