      c.classList.remove('active');
      c.setAttribute('aria-pressed', 'false');
    });
    chip.classList.add('active');
    chip.setAttribute('aria-pressed', 'true');

    const cat = chip.dataset.category;
    const filtered = cat === 'all' ? PRODUCTS : PRODUCTS.filter(p => p.category.toLowerCase() === cat);
    productsGrid.innerHTML = renderProducts(filtered.length ? filtered : PRODUCTS);

    // Re-bind buttons after re-render
    productsGrid.querySelectorAll('.btn-add-cart').forEach(btn => {
      btn.addEventListener('click', () => {
        const product = PRODUCTS.find(p => p.id === +btn.dataset.id);
        addToCart(product);
        btn.classList.add('added');
        btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Added!`;
        setTimeout(() => {
          btn.classList.remove('added');
          btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg> Add to Cart`;
        }, 2000);
      });
    });
    productsGrid.querySelectorAll('.product-wishlist').forEach(btn => {
      btn.addEventListener('click', () => {
        const isActive = btn.classList.toggle('active');
        btn.setAttribute('aria-pressed', isActive);
        const name = btn.closest('.product-card').querySelector('.product-name').textContent;
        showToast(isActive ? '❤️' : '🤍', isActive ? `${name} saved to wishlist` : `${name} removed from wishlist`);
      });
    });
  });
});

// ============================================================
// CART OPEN BUTTON
// ============================================================
document.querySelectorAll('[aria-label="Open cart"]').forEach(btn => {
  btn.addEventListener('click', openCart);
});

// ============================================================
// NEWSLETTER
// ============================================================
document.getElementById('newsletter-form').addEventListener('submit', e => {
  e.preventDefault();
  const input = e.target.querySelector('input[type="email"]');
  const email = input.value.trim();
  if (!email) return;
  input.value = '';
  showToast('🎉', `You're subscribed! Check your inbox.`);
});

// ============================================================
// MOBILE NAV
// ============================================================
const hamburger = document.getElementById('nav-hamburger');
const navLinks  = document.getElementById('nav-links');
let navOpen = false;

hamburger.addEventListener('click', () => {
  navOpen = !navOpen;
  navLinks.style.display = navOpen ? 'flex' : '';
  navLinks.style.flexDirection = 'column';
  navLinks.style.position = 'absolute';
  navLinks.style.top = '64px';
  navLinks.style.left = '0';
  navLinks.style.right = '0';
  navLinks.style.background = 'var(--bg-base)';
  navLinks.style.borderBottom = '1px solid var(--border)';
  navLinks.style.padding = '1rem 1.5rem';
  hamburger.setAttribute('aria-expanded', navOpen);
});

// ============================================================
// SCROLL ANIMATIONS
// ============================================================
const observer = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.style.opacity = '1';
      entry.target.style.transform = 'translateY(0)';
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.1 });

document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach(el => {
  el.style.opacity = '0';
  el.style.transform = 'translateY(20px)';
  el.style.transition = 'opacity .45s ease, transform .45s ease, box-shadow .22s ease, border-color .22s ease';
  observer.observe(el);
});
