// ============================================================
// STATE
// ============================================================
let cart = [];
let countdownTimers = {};

// ============================================================
// HELPERS
// ============================================================
function stars(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5;
  let html = '';
  for (let i = 0; i < 5; i++) {
    if (i < full)           html += '<span aria-hidden="true">★</span>';
    else if (i === full && half) html += '<span aria-hidden="true">½</span>';
    else                    html += '<span class="star-empty" aria-hidden="true">★</span>';
  }
  return html;
}

function formatPrice(n) {
  return '$' + n.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function discount(orig, now) {
  return Math.round((1 - now / orig) * 100);
}

function padTwo(n) { return String(n).padStart(2, '0'); }

function formatCountdown(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return { h: padTwo(h), m: padTwo(m), s: padTwo(s) };
}

// ============================================================
// TOAST
// ============================================================
const toastContainer = document.getElementById('toast-container');

function showToast(icon, message, duration = 3000) {
  const el = document.createElement('div');
  el.className = 'toast';
  el.setAttribute('role', 'status');
  el.setAttribute('aria-live', 'polite');
  el.innerHTML = `<span class="toast-icon" aria-hidden="true">${icon}</span><span>${message}</span>`;
  toastContainer.appendChild(el);

  setTimeout(() => {
    el.classList.add('exiting');
    el.addEventListener('animationend', () => el.remove());
  }, duration);
}

// ============================================================
// CART
// ============================================================
const cartOverlay  = document.getElementById('cart-overlay');
const cartDrawer   = document.getElementById('cart-drawer');
const cartItemsEl  = document.getElementById('cart-items');
const cartCountEl  = document.querySelectorAll('.cart-count');
const cartTotalEl  = document.getElementById('cart-total');
const cartSubtotalEl = document.getElementById('cart-subtotal');

function openCart() {
  cartOverlay.classList.add('open');
  cartDrawer.classList.add('open');
  cartDrawer.setAttribute('aria-hidden', 'false');
  document.getElementById('cart-close').focus();
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  cartOverlay.classList.remove('open');
  cartDrawer.classList.remove('open');
  cartDrawer.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
  document.querySelector('[aria-label="Open cart"]').focus();
}

cartOverlay.addEventListener('click', closeCart);
document.getElementById('cart-close').addEventListener('click', closeCart);
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeCart(); });

function addToCart(product) {
  const existing = cart.find(i => i.id === product.id);
  if (existing) {
    existing.qty++;
  } else {
    cart.push({ ...product, qty: 1 });
  }
  renderCart();
  showToast('🛒', `<strong>${product.name}</strong> added to cart`);
}

function removeFromCart(id) {
  cart = cart.filter(i => i.id !== id);
  renderCart();
}

function changeQty(id, delta) {
  const item = cart.find(i => i.id === id);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) return removeFromCart(id);
  renderCart();
}

function renderCart() {
  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
  const count = cart.reduce((s, i) => s + i.qty, 0);

  cartCountEl.forEach(el => {
    el.textContent = count;
    el.hidden = count === 0;
  });

  if (cart.length === 0) {
    cartItemsEl.innerHTML = `
      <div class="cart-empty" role="status">
        <span class="cart-empty-icon" aria-hidden="true">🛒</span>
        <p>Your cart is empty</p>
        <a href="#featured-products" class="btn btn-ghost" style="font-size:.85rem;padding:.5rem 1rem;" onclick="closeCart()">Browse products</a>
      </div>`;
  } else {
    cartItemsEl.innerHTML = cart.map(item => `
      <div class="cart-item" aria-label="${item.name}, quantity ${item.qty}">
        <div class="cart-item-emoji" aria-hidden="true">${item.emoji}</div>
        <div class="cart-item-info">
          <div class="cart-item-name">${item.name}</div>
          <div class="cart-item-price">${formatPrice(item.price)}</div>
          <div class="cart-item-qty">
            <button class="qty-btn" aria-label="Decrease quantity of ${item.name}" data-id="${item.id}" data-delta="-1">−</button>
            <span class="qty-num" aria-live="polite">${item.qty}</span>
            <button class="qty-btn" aria-label="Increase quantity of ${item.name}" data-id="${item.id}" data-delta="1">+</button>
          </div>
        </div>
        <button class="cart-item-remove" aria-label="Remove ${item.name} from cart" data-id="${item.id}">✕</button>
      </div>`).join('');
  }

  const shipping = total > 0 ? (total >= 100 ? 0 : 7.99) : 0;
  cartSubtotalEl.textContent = formatPrice(total);
  document.getElementById('cart-shipping').textContent = shipping === 0 ? 'FREE' : formatPrice(shipping);
  cartTotalEl.textContent = formatPrice(total + shipping);

  // bind qty and remove buttons
  cartItemsEl.querySelectorAll('.qty-btn').forEach(btn => {
    btn.addEventListener('click', () => changeQty(+btn.dataset.id, +btn.dataset.delta));
  });
  cartItemsEl.querySelectorAll('.cart-item-remove').forEach(btn => {
    btn.addEventListener('click', () => removeFromCart(+btn.dataset.id));
  });
}

// Initial render
renderCart();

